import{_ as r,o as a,c as i,a3 as t}from"./chunks/framework.BrO6lPIi.js";const p=JSON.parse('{"title":"扩展相关问题","description":"本文件面向“AI Helper”扩展（Chrome 扩展端，Manifest V3，版本 2.7.0）与其独立本地代理端 Agent（Node.js，包名 ai-helper-agent，版本 2.7.0）的扩展相关问题排查。","frontmatter":{"title":"扩展相关问题","description":"本文件面向“AI Helper”扩展（Chrome 扩展端，Manifest V3，版本 2.7.0）与其独立本地代理端 Agent（Node.js，包名 ai-helper-agent，版本 2.7.0）的扩展相关问题排查。"},"headers":[],"relativePath":"故障排除与常见问题/扩展相关问题/index.md","filePath":"故障排除与常见问题/扩展相关问题/index.md","lastUpdated":null}'),l={name:"故障排除与常见问题/扩展相关问题/index.md"};function o(n,e,s,c,h,g){return a(),i("div",null,[...e[0]||(e[0]=[t(`<h1 id="扩展相关问题" tabindex="-1">扩展相关问题 <a class="header-anchor" href="#扩展相关问题" aria-label="Permalink to &quot;扩展相关问题&quot;">​</a></h1><details class="details custom-block"><summary>本文引用的源码文件</summary><p><strong>本文引用的文件</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/manifest.json" target="_blank" rel="noreferrer">manifest.json</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/index.js" target="_blank" rel="noreferrer">src/background/index.js</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/storage/db.js" target="_blank" rel="noreferrer">src/storage/db.js</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/side_panel/export-import.js" target="_blank" rel="noreferrer">src/side_panel/export-import.js</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/options/config-manager.js" target="_blank" rel="noreferrer">src/options/config-manager.js</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js" target="_blank" rel="noreferrer">agent/src/server.js</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/install-mode.js" target="_blank" rel="noreferrer">agent/src/install-mode.js</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/security.js" target="_blank" rel="noreferrer">agent/src/security.js</a></li></ul></details><h2 id="目录" tabindex="-1">目录 <a class="header-anchor" href="#目录" aria-label="Permalink to &quot;目录&quot;">​</a></h2><ol><li><a href="#引言">引言</a></li><li><a href="#项目结构与排查边界">项目结构与排查边界</a></li><li><a href="#扩展更新失败常见原因与解决方法">扩展更新失败：常见原因与解决方法</a></li><li><a href="#配置重置用户设置备份恢复与缓存清理">配置重置：用户设置备份、恢复与缓存清理</a></li><li><a href="#数据恢复流程会话导出导入历史恢复与知识库重建">数据恢复流程：会话导出导入、历史恢复与知识库重建</a></li><li><a href="#扩展卸载与完整清理步骤">扩展卸载与完整清理步骤</a></li><li><a href="#扩展权限管理与安全最佳实践">扩展权限管理与安全最佳实践</a></li><li><a href="#崩溃保护与灾难恢复方案">崩溃保护与灾难恢复方案</a></li><li><a href="#依赖关系与架构总览">依赖关系与架构总览</a></li><li><a href="#故障排查清单">故障排查清单</a></li><li><a href="#结论">结论</a></li></ol><h2 id="引言" tabindex="-1">引言 <a class="header-anchor" href="#引言" aria-label="Permalink to &quot;引言&quot;">​</a></h2><p>本文件面向“AI Helper”扩展（Chrome 扩展端，Manifest V3，版本 2.7.0）与其独立本地代理端 Agent（Node.js，包名 ai-helper-agent，版本 2.7.0）的扩展相关问题排查。文档重点覆盖以下目标：</p><ul><li>扩展更新失败的常见原因与修复路径；</li><li>配置重置的具体步骤，包括用户设置备份、默认配置重置和缓存清理；</li><li>数据恢复流程，包括 IndexedDB 数据导出导入、会话历史恢复和知识库重建；</li><li>扩展卸载后的完整清理步骤，包括文件残留、注册表/系统状态和服务进程终止；</li><li>扩展权限管理最佳实践；</li><li>扩展崩溃后的数据保护机制与灾难恢复方案。</li></ul><p>需要特别强调：扩展端与 Agent 端通过本地 HTTP/WebSocket 通信，Agent 源码修改后必须重启进程，新接口才生效。因此任何涉及 Agent 行为变更的修复，都应包含“重启 Agent 进程”这一动作。</p><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/manifest.json#L1-L76" target="_blank" rel="noreferrer">manifest.json#L1-L76</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js#L388-L443" target="_blank" rel="noreferrer">agent/src/server.js#L388-L443</a></li></ul><h2 id="项目结构与排查边界" tabindex="-1">项目结构与排查边界 <a class="header-anchor" href="#项目结构与排查边界" aria-label="Permalink to &quot;项目结构与排查边界&quot;">​</a></h2><p>本项目采用双进程架构：</p><ul><li>Chrome 扩展端位于 <code>src/</code>，入口为 Service Worker <code>src/background/index.js</code>，负责侧边栏、消息路由、ReAct 任务调度、IndexedDB 持久化、与 Agent 的本地通信。</li><li>Agent 端位于 <code>agent/src/server.js</code>，提供 HTTP + WebSocket 接口，暴露文件读写、命令执行、长期记忆、RAG、MCP、技能等能力。</li></ul><pre class="mermaid">graph TB
Browser[&quot;浏览器扩展环境&lt;br/&gt;Manifest V3&quot;]
Background[&quot;Background Service Worker&lt;br/&gt;src/background/index.js&quot;]
SidePanel[&quot;Side Panel 界面&lt;br/&gt;会话/工具/知识面板&quot;]
Storage[&quot;IndexedDB&lt;br/&gt;ai-helper-db&quot;]
LocalStorage[&quot;chrome.storage.local&lt;br/&gt;配置/后备 checkpoint&quot;]
AgentServer[&quot;Agent 本地服务器&lt;br/&gt;agent/src/server.js&quot;]
FileSystem[&quot;工作目录与系统文件&quot;]
RAG[&quot;RAG 知识库与向量索引&quot;]
Browser --&gt; Background
Browser --&gt; SidePanel
Background --&gt; Storage
Background --&gt; LocalStorage
Background --&gt; AgentServer
AgentServer --&gt; FileSystem
AgentServer --&gt; RAG
</pre><p><strong>图表来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/index.js#L1-L120" target="_blank" rel="noreferrer">src/background/index.js#L1-L120</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/storage/db.js#L21-L92" target="_blank" rel="noreferrer">src/storage/db.js#L21-L92</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js#L388-L500" target="_blank" rel="noreferrer">agent/src/server.js#L388-L500</a></li></ul><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/manifest.json#L1-L76" target="_blank" rel="noreferrer">manifest.json#L1-L76</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/index.js#L1-L120" target="_blank" rel="noreferrer">src/background/index.js#L1-L120</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/storage/db.js#L21-L92" target="_blank" rel="noreferrer">src/storage/db.js#L21-L92</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js#L388-L500" target="_blank" rel="noreferrer">agent/src/server.js#L388-L500</a></li></ul><h2 id="扩展更新失败-常见原因与解决方法" tabindex="-1">扩展更新失败：常见原因与解决方法 <a class="header-anchor" href="#扩展更新失败-常见原因与解决方法" aria-label="Permalink to &quot;扩展更新失败：常见原因与解决方法&quot;">​</a></h2><h3 id="_1-版本冲突" tabindex="-1">1. 版本冲突 <a class="header-anchor" href="#_1-版本冲突" aria-label="Permalink to &quot;1. 版本冲突&quot;">​</a></h3><p>扩展端与 Agent 端版本号应保持同步。当前仓库中扩展端版本为 2.7.0，Agent 端也应以 2.7.0 为准。若出现“扩展可用但 Agent 功能异常”，应优先检查两端版本是否一致。</p><p>排查建议：</p><ul><li>查看扩展版本：在 Chrome 扩展管理页面确认扩展版本是否为 2.7.0。</li><li>查看 Agent 版本：调用 Agent 健康接口 <code>/api/status</code>，返回字段中包含 <code>version</code>。</li><li>若版本不一致，先升级 Agent 端，再刷新扩展。</li></ul><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/manifest.json#L1-L10" target="_blank" rel="noreferrer">manifest.json#L1-L10</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js#L487-L500" target="_blank" rel="noreferrer">agent/src/server.js#L487-L500</a></li></ul><h3 id="_2-npm-全局安装失败或超时" tabindex="-1">2. npm 全局安装失败或超时 <a class="header-anchor" href="#_2-npm-全局安装失败或超时" aria-label="Permalink to &quot;2. npm 全局安装失败或超时&quot;">​</a></h3><p>Agent 更新通过服务端 <code>/api/agent/update</code> 触发 <code>npm install -g ai-helper-agent@latest</code>。该过程存在以下风险：</p><ul><li>网络不可用或镜像源不可达；</li><li>npm 被其他进程占用；</li><li>安装超时（默认 90 秒保护）；</li><li>与 RAG 依赖安装并发写 <code>node_modules</code>，导致互相破坏。</li></ul><p>修复步骤：</p><ol><li>停止正在进行的 RAG 安装或更新操作。</li><li>手动执行 <code>npm install -g ai-helper-agent@latest</code>，观察输出日志。</li><li>若提示权限问题，使用管理员权限或调整 npm 全局目录权限。</li><li>更新成功后重启 Agent 进程。</li></ol><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js#L605-L720" target="_blank" rel="noreferrer">agent/src/server.js#L605-L720</a></li></ul><h3 id="_3-端口占用或服务未启动" tabindex="-1">3. 端口占用或服务未启动 <a class="header-anchor" href="#_3-端口占用或服务未启动" aria-label="Permalink to &quot;3. 端口占用或服务未启动&quot;">​</a></h3><p>Agent 监听本地端口，若端口被占用或进程未启动，扩展无法连接。</p><p>排查建议：</p><ul><li>检查 Agent 是否运行：访问 <code>/api/status</code>。</li><li>检查端口是否被占用：根据配置中的 <code>host</code> 与 <code>port</code> 判断。</li><li>若服务已启动但无响应，执行 <code>/api/shutdown</code> 或手动终止进程后重新启动。</li></ul><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js#L388-L443" target="_blank" rel="noreferrer">agent/src/server.js#L388-L443</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js#L502-L535" target="_blank" rel="noreferrer">agent/src/server.js#L502-L535</a></li></ul><h3 id="_4-内嵌模式与-npm-全局模式路径差异" tabindex="-1">4. 内嵌模式与 npm 全局模式路径差异 <a class="header-anchor" href="#_4-内嵌模式与-npm-全局模式路径差异" aria-label="Permalink to &quot;4. 内嵌模式与 npm 全局模式路径差异&quot;">​</a></h3><p>Agent 支持两种运行模式：</p><ul><li>内嵌模式：由安装脚本安装到 <code>~/.ai-helper-agent/</code>；</li><li>npm 全局模式：传统 <code>npm install -g</code> 路径。</li></ul><p>若更新后路径解析异常，应检查当前是否为内嵌模式，并确认 Node/npm 可执行文件路径是否正确。</p><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/install-mode.js#L1-L129" target="_blank" rel="noreferrer">agent/src/install-mode.js#L1-L129</a></li></ul><h3 id="_5-权限变更导致-agent-无法写入" tabindex="-1">5. 权限变更导致 Agent 无法写入 <a class="header-anchor" href="#_5-权限变更导致-agent-无法写入" aria-label="Permalink to &quot;5. 权限变更导致 Agent 无法写入&quot;">​</a></h3><p>Agent 对核心敏感路径有硬阻止策略，例如配置文件、配对记录、日志目录、回收站等。若更新过程中尝试写入这些路径，会被安全模块拦截。</p><p>修复建议：</p><ul><li>不要将工作目录设置为 Agent 内部目录；</li><li>使用用户可控的工作目录；</li><li>避免直接修改 <code>config.json</code>、<code>pairings.json</code>、<code>mcp_servers.json</code> 等核心文件。</li></ul><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/security.js#L62-L100" target="_blank" rel="noreferrer">agent/src/security.js#L62-L100</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/security.js#L109-L229" target="_blank" rel="noreferrer">agent/src/security.js#L109-L229</a></li></ul><h2 id="配置重置-用户设置备份、恢复与缓存清理" tabindex="-1">配置重置：用户设置备份、恢复与缓存清理 <a class="header-anchor" href="#配置重置-用户设置备份、恢复与缓存清理" aria-label="Permalink to &quot;配置重置：用户设置备份、恢复与缓存清理&quot;">​</a></h2><h3 id="_1-用户设置的备份" tabindex="-1">1. 用户设置的备份 <a class="header-anchor" href="#_1-用户设置的备份" aria-label="Permalink to &quot;1. 用户设置的备份&quot;">​</a></h3><p>扩展端主要配置存储在 <code>chrome.storage.local</code>，包括模型列表、API Base URL、图片识别模型、自定义 API Base、删除过的预设项等。</p><p>推荐备份方式：</p><ul><li>打开选项页，进入模型与 API Base 管理界面；</li><li>记录自定义模型名称、上下文窗口大小、API Base URL 及标签；</li><li>如需完整备份，可使用浏览器开发者工具读取 <code>chrome.storage.local</code> 内容并保存 JSON。</li></ul><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/options/config-manager.js#L269-L283" target="_blank" rel="noreferrer">src/options/config-manager.js#L269-L283</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/options/config-manager.js#L485-L583" target="_blank" rel="noreferrer">src/options/config-manager.js#L485-L583</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/options/config-manager.js#L700-L764" target="_blank" rel="noreferrer">src/options/config-manager.js#L700-L764</a></li></ul><h3 id="_2-默认配置的重置" tabindex="-1">2. 默认配置的重置 <a class="header-anchor" href="#_2-默认配置的重置" aria-label="Permalink to &quot;2. 默认配置的重置&quot;">​</a></h3><p>若配置损坏或行为异常，可按以下步骤重置：</p><ol><li>打开 Chrome 扩展设置页；</li><li>找到 AI Helper 扩展；</li><li>点击“清除数据”或“重置设置”；</li><li>重新打开选项页，加载默认模型与 API Base；</li><li>重新输入必要的密钥或 API Base。</li></ol><p>注意：重置会清空 <code>chrome.storage.local</code> 中的扩展配置，但不会自动删除 IndexedDB 中的会话数据。</p><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/manifest.json#L7-L32" target="_blank" rel="noreferrer">manifest.json#L7-L32</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/options/config-manager.js#L269-L283" target="_blank" rel="noreferrer">src/options/config-manager.js#L269-L283</a></li></ul><h3 id="_3-缓存数据的清理" tabindex="-1">3. 缓存数据的清理 <a class="header-anchor" href="#_3-缓存数据的清理" aria-label="Permalink to &quot;3. 缓存数据的清理&quot;">​</a></h3><p>扩展端涉及两类缓存：</p><ul><li><code>chrome.storage.local</code>：轻量配置、临时状态；</li><li>IndexedDB <code>ai-helper-db</code>：会话、归档会话、UI 原型、Token 统计、ReAct checkpoint、书签、定时任务等。</li></ul><p>清理建议：</p><ul><li>仅清理配置：清除扩展数据；</li><li>仅清理会话：通过侧边栏导出重要会话后，再删除 IndexedDB 中的 <code>sessions</code> 与 <code>archivedSessions</code>；</li><li>完全重置：清除扩展数据 + 删除 IndexedDB + 重启 Agent。</li></ul><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/storage/db.js#L21-L92" target="_blank" rel="noreferrer">src/storage/db.js#L21-L92</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/storage/db.js#L547-L602" target="_blank" rel="noreferrer">src/storage/db.js#L547-L602</a></li></ul><h2 id="数据恢复流程-会话导出导入、历史恢复与知识库重建" tabindex="-1">数据恢复流程：会话导出导入、历史恢复与知识库重建 <a class="header-anchor" href="#数据恢复流程-会话导出导入、历史恢复与知识库重建" aria-label="Permalink to &quot;数据恢复流程：会话导出导入、历史恢复与知识库重建&quot;">​</a></h2><h3 id="_1-会话导出与导入" tabindex="-1">1. 会话导出与导入 <a class="header-anchor" href="#_1-会话导出与导入" aria-label="Permalink to &quot;1. 会话导出与导入&quot;">​</a></h3><p>侧边栏提供会话导出/导入功能，导出格式为 <code>.aihelper.json</code>，包含会话标题、模型、工具配置、温度、TopP、消息历史等。</p><p>导出流程：</p><ol><li>打开侧边栏；</li><li>进入会话导出界面；</li><li>选择要导出的会话；</li><li>点击导出，生成 JSON 文件；</li><li>将文件保存到安全位置。</li></ol><p>导入流程：</p><ol><li>准备 <code>.aihelper.json</code> 文件或兼容旧格式的消息数组；</li><li>在侧边栏导入界面选择文件；</li><li>系统校验格式并导入会话；</li><li>刷新会话标签栏。</li></ol><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/side_panel/export-import.js#L48-L124" target="_blank" rel="noreferrer">src/side_panel/export-import.js#L48-L124</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/side_panel/export-import.js#L152-L220" target="_blank" rel="noreferrer">src/side_panel/export-import.js#L152-L220</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/side_panel/export-import.js#L256-L305" target="_blank" rel="noreferrer">src/side_panel/export-import.js#L256-L305</a></li></ul><h3 id="_2-indexeddb-数据迁移与自检" tabindex="-1">2. IndexedDB 数据迁移与自检 <a class="header-anchor" href="#_2-indexeddb-数据迁移与自检" aria-label="Permalink to &quot;2. IndexedDB 数据迁移与自检&quot;">​</a></h3><p>扩展启动时会检查 IndexedDB 是否已有会话数据；若无，则尝试从 <code>chrome.storage.local</code> 迁移旧数据。迁移完成后会清理旧的会话 key。</p><p>此外，数据库封装层对 <code>reactCheckpoints</code> store 缺失做了防御性处理：若 store 不存在，会关闭连接并重试，以应对 SW 重启或 DB 升级导致的连接陈旧问题。</p><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/storage/db.js#L547-L602" target="_blank" rel="noreferrer">src/storage/db.js#L547-L602</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/storage/db.js#L154-L252" target="_blank" rel="noreferrer">src/storage/db.js#L154-L252</a></li></ul><h3 id="_3-react-checkpoint-的双写后备机制" tabindex="-1">3. ReAct Checkpoint 的双写后备机制 <a class="header-anchor" href="#_3-react-checkpoint-的双写后备机制" aria-label="Permalink to &quot;3. ReAct Checkpoint 的双写后备机制&quot;">​</a></h3><p>当长任务被 Service Worker 回收时，扩展会保存 ReAct checkpoint，以便后续自动续跑。checkpoint 同时写入：</p><ul><li><code>chrome.storage.local</code>（可靠后备）；</li><li>IndexedDB <code>reactCheckpoints</code>（性能优化）。</li></ul><p>若 IndexedDB 不可用，checkpoint 仍可保留在 storage.local 中，避免中断任务丢失。</p><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/storage/db.js#L626-L703" target="_blank" rel="noreferrer">src/storage/db.js#L626-L703</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/index.js#L56-L95" target="_blank" rel="noreferrer">src/background/index.js#L56-L95</a></li></ul><h3 id="_4-知识库重建方法" tabindex="-1">4. 知识库重建方法 <a class="header-anchor" href="#_4-知识库重建方法" aria-label="Permalink to &quot;4. 知识库重建方法&quot;">​</a></h3><p>Agent 端的 RAG 能力依赖本地依赖与环境检测。若 RAG 不可用，可能表现为知识库无法检索或重建失败。</p><p>重建建议：</p><ol><li>检查 Agent 健康接口 <code>/api/status</code> 中的 <code>ragAvailable</code>；</li><li>若不可用，查看 RAG 安装日志；</li><li>若曾成功安装但依赖被清（例如 npm 全局更新），Agent 会自动尝试恢复 RAG 依赖；</li><li>若仍失败，手动安装 RAG 相关依赖；</li><li>重建知识库索引。</li></ol><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js#L401-L407" target="_blank" rel="noreferrer">agent/src/server.js#L401-L407</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js#L487-L500" target="_blank" rel="noreferrer">agent/src/server.js#L487-L500</a></li></ul><h2 id="扩展卸载与完整清理步骤" tabindex="-1">扩展卸载与完整清理步骤 <a class="header-anchor" href="#扩展卸载与完整清理步骤" aria-label="Permalink to &quot;扩展卸载与完整清理步骤&quot;">​</a></h2><h3 id="_1-扩展本身卸载" tabindex="-1">1. 扩展本身卸载 <a class="header-anchor" href="#_1-扩展本身卸载" aria-label="Permalink to &quot;1. 扩展本身卸载&quot;">​</a></h3><p>在 Chrome 扩展管理页面移除 AI Helper 扩展。这会删除扩展代码和部分扩展数据，但不会自动清理：</p><ul><li>Agent 本地服务进程；</li><li>Agent 工作目录；</li><li><code>~/.ai-helper-agent/</code> 下的内嵌运行时；</li><li>系统级 npm 全局包（如果是 npm 全局安装）。</li></ul><h3 id="_2-agent-服务进程终止" tabindex="-1">2. Agent 服务进程终止 <a class="header-anchor" href="#_2-agent-服务进程终止" aria-label="Permalink to &quot;2. Agent 服务进程终止&quot;">​</a></h3><p>Agent 是独立 Node.js 进程，卸载扩展不会自动终止它。</p><p>终止方式：</p><ul><li>使用 Agent 提供的 <code>/api/shutdown</code> 接口；</li><li>或通过系统任务管理器查找并终止 Node 进程；</li><li>内嵌模式下，检查 <code>~/.ai-helper-agent/</code> 下是否有残留进程。</li></ul><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js#L502-L535" target="_blank" rel="noreferrer">agent/src/server.js#L502-L535</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/install-mode.js#L102-L107" target="_blank" rel="noreferrer">agent/src/install-mode.js#L102-L107</a></li></ul><h3 id="_3-文件残留清理" tabindex="-1">3. 文件残留清理 <a class="header-anchor" href="#_3-文件残留清理" aria-label="Permalink to &quot;3. 文件残留清理&quot;">​</a></h3><h4 id="内嵌模式" tabindex="-1">内嵌模式 <a class="header-anchor" href="#内嵌模式" aria-label="Permalink to &quot;内嵌模式&quot;">​</a></h4><p>内嵌模式会将运行时和应用安装在 <code>~/.ai-helper-agent/</code>。卸载时应检查：</p><ul><li><code>~/.ai-helper-agent/runtime/</code>；</li><li><code>~/.ai-helper-agent/app/</code>；</li><li><code>~/.ai-helper-agent/config.json</code>；</li><li><code>~/.ai-helper-agent/logs/</code>；</li><li><code>~/.ai-helper-agent/.trash/</code>；</li><li><code>~/.ai-helper-agent/mirrors.json</code>；</li><li><code>~/.ai-helper-agent/INSTALL_MANIFEST.json</code>。</li></ul><h4 id="npm-全局模式" tabindex="-1">npm 全局模式 <a class="header-anchor" href="#npm-全局模式" aria-label="Permalink to &quot;npm 全局模式&quot;">​</a></h4><p>npm 全局安装的 Agent 包通常位于 Node 全局包目录，例如：</p><ul><li>macOS/Linux：<code>/usr/local/lib/node_modules/ai-helper-agent</code> 或用户 npm prefix；</li><li>Windows：Node 全局模块目录。</li></ul><h4 id="工作目录" tabindex="-1">工作目录 <a class="header-anchor" href="#工作目录" aria-label="Permalink to &quot;工作目录&quot;">​</a></h4><p>Agent 的 <code>workdir</code> 由配置决定，默认可能是用户当前工作目录。卸载前应先确认工作目录中是否有用户数据，不要误删。</p><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/install-mode.js#L15-L32" target="_blank" rel="noreferrer">agent/src/install-mode.js#L15-L32</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/install-mode.js#L64-L121" target="_blank" rel="noreferrer">agent/src/install-mode.js#L64-L121</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/security.js#L62-L75" target="_blank" rel="noreferrer">agent/src/security.js#L62-L75</a></li></ul><h3 id="_4-注册表与系统状态清理" tabindex="-1">4. 注册表与系统状态清理 <a class="header-anchor" href="#_4-注册表与系统状态清理" aria-label="Permalink to &quot;4. 注册表与系统状态清理&quot;">​</a></h3><p>Agent 的安全模块对命令执行进行分级管控，其中包含 Windows 注册表相关命令的灰名单。但扩展本身不直接维护 Windows 注册表条目；若用户通过 Agent 命令修改过系统状态，需按系统常规方式清理。</p><p>注意：</p><ul><li>不应盲目删除系统注册表；</li><li>只清理明确由用户创建的条目；</li><li>若不确定，请先导出注册表备份。</li></ul><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/security.js#L371-L384" target="_blank" rel="noreferrer">agent/src/security.js#L371-L384</a></li></ul><h2 id="扩展权限管理与安全最佳实践" tabindex="-1">扩展权限管理与安全最佳实践 <a class="header-anchor" href="#扩展权限管理与安全最佳实践" aria-label="Permalink to &quot;扩展权限管理与安全最佳实践&quot;">​</a></h2><h3 id="_1-manifest-权限说明" tabindex="-1">1. Manifest 权限说明 <a class="header-anchor" href="#_1-manifest-权限说明" aria-label="Permalink to &quot;1. Manifest 权限说明&quot;">​</a></h3><p>扩展声明了较多权限，包括 <code>activeTab</code>、<code>storage</code>、<code>unlimitedStorage</code>、<code>sidePanel</code>、<code>scripting</code>、<code>bookmarks</code>、<code>history</code>、<code>downloads</code>、<code>notifications</code>、<code>tabs</code>、<code>tabGroups</code>、<code>cookies</code>、<code>offscreen</code>、<code>clipboardRead</code>、<code>clipboardWrite</code>、<code>commands</code>、<code>alarms</code>、<code>debugger</code>、<code>webNavigation</code>，以及主机权限 <code>&lt;all_urls&gt;</code>、<code>http://*/*</code>、<code>https://*/*</code>。</p><p>最小权限原则建议：</p><ul><li>仅在确实需要时启用对应功能；</li><li>避免将扩展分发给不需要全部能力的用户；</li><li>定期审计权限使用情况；</li><li>对敏感权限（如 <code>cookies</code>、<code>history</code>、<code>debugger</code>）做额外风险评估。</li></ul><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/manifest.json#L7-L32" target="_blank" rel="noreferrer">manifest.json#L7-L32</a></li></ul><h3 id="_2-agent-端安全控制" tabindex="-1">2. Agent 端安全控制 <a class="header-anchor" href="#_2-agent-端安全控制" aria-label="Permalink to &quot;2. Agent 端安全控制&quot;">​</a></h3><p>Agent 端实现了两层关键安全控制：</p><ul><li>文件路径沙箱：白名单 + 硬阻止目录 + 符号链接校验；</li><li>命令分级管控：黑名单绝对禁止，灰名单需用户确认。</li></ul><p>最佳实践：</p><ul><li>将工作目录限制在用户可控目录；</li><li>不在 <code>allowedPaths</code> 中添加系统目录；</li><li>谨慎授权高风险命令；</li><li>开启确认弹窗，不要长期关闭安全提示；</li><li>定期检查 Agent 日志。</li></ul><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/security.js#L109-L229" target="_blank" rel="noreferrer">agent/src/security.js#L109-L229</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/security.js#L285-L384" target="_blank" rel="noreferrer">agent/src/security.js#L285-L384</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/security.js#L691-L758" target="_blank" rel="noreferrer">agent/src/security.js#L691-L758</a></li></ul><h3 id="_3-cors-与来源限制" tabindex="-1">3. CORS 与来源限制 <a class="header-anchor" href="#_3-cors-与来源限制" aria-label="Permalink to &quot;3. CORS 与来源限制&quot;">​</a></h3><p>Agent 服务器仅允许来自 <code>chrome-extension://</code> 的请求跨域读取响应，防止恶意网页直接调用无认证接口。</p><p>建议：</p><ul><li>不要将 Agent 绑定到 <code>0.0.0.0</code> 且对外暴露；</li><li>生产环境建议使用本机回环地址；</li><li>若需远程访问，必须启用认证并通过安全网关。</li></ul><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js#L235-L266" target="_blank" rel="noreferrer">agent/src/server.js#L235-L266</a></li></ul><h2 id="崩溃保护与灾难恢复方案" tabindex="-1">崩溃保护与灾难恢复方案 <a class="header-anchor" href="#崩溃保护与灾难恢复方案" aria-label="Permalink to &quot;崩溃保护与灾难恢复方案&quot;">​</a></h2><h3 id="_1-service-worker-生命周期与保活" tabindex="-1">1. Service Worker 生命周期与保活 <a class="header-anchor" href="#_1-service-worker-生命周期与保活" aria-label="Permalink to &quot;1. Service Worker 生命周期与保活&quot;">​</a></h3><p>Chrome MV3 的 Service Worker 可能被系统回收。扩展通过 keepalive port 机制保持活跃，并在 SW 重启后检测断连，向面板发送 <code>SW_RESTARTED</code> 消息，附带可恢复的 checkpoint 元数据。</p><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/index.js#L121-L218" target="_blank" rel="noreferrer">src/background/index.js#L121-L218</a></li></ul><h3 id="_2-react-任务自动续跑" tabindex="-1">2. ReAct 任务自动续跑 <a class="header-anchor" href="#_2-react-任务自动续跑" aria-label="Permalink to &quot;2. ReAct 任务自动续跑&quot;">​</a></h3><p>扩展在后台注册闹钟处理器，扫描残留 checkpoint 并尝试自动续跑。续跑次数超过上限后会通知用户人工介入。</p><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/index.js#L56-L81" target="_blank" rel="noreferrer">src/background/index.js#L56-L81</a></li></ul><h3 id="_3-indexeddb-连接恢复与-store-重建" tabindex="-1">3. IndexedDB 连接恢复与 store 重建 <a class="header-anchor" href="#_3-indexeddb-连接恢复与-store-重建" aria-label="Permalink to &quot;3. IndexedDB 连接恢复与 store 重建&quot;">​</a></h3><p>数据库封装层对事务错误、连接关闭、store 缺失等情况进行重试与连接重置，确保 SW 重启后仍能访问必要的数据结构。</p><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/storage/db.js#L154-L252" target="_blank" rel="noreferrer">src/storage/db.js#L154-L252</a></li></ul><h3 id="_4-灾难恢复流程" tabindex="-1">4. 灾难恢复流程 <a class="header-anchor" href="#_4-灾难恢复流程" aria-label="Permalink to &quot;4. 灾难恢复流程&quot;">​</a></h3><p>若扩展或 Agent 发生严重异常，建议按以下顺序恢复：</p><ol><li>导出所有重要会话；</li><li>检查 Agent 是否正常运行；</li><li>若 Agent 异常，重启 Agent；</li><li>若会话丢失，尝试从 <code>.aihelper.json</code> 导入；</li><li>若 IndexedDB 损坏，先导出备份，再考虑重置扩展数据；</li><li>若知识库失效，重建 RAG 索引；</li><li>最后恢复用户配置。</li></ol><pre class="mermaid">flowchart TD
Start[&quot;发现异常&quot;] --&gt; ExportSessions[&quot;导出重要会话&quot;]
ExportSessions --&gt; CheckAgent[&quot;检查 Agent 状态&quot;]
CheckAgent --&gt; AgentRunning{&quot;Agent 正常?&quot;}
AgentRunning --&gt; |否| RestartAgent[&quot;重启 Agent&quot;]
AgentRunning --&gt; |是| CheckData[&quot;检查会话数据&quot;]
RestartAgent --&gt; CheckData
CheckData --&gt; DataExists{&quot;会话是否存在?&quot;}
DataExists --&gt; |是| RestoreKB[&quot;检查知识库可用性&quot;]
DataExists --&gt; |否| ImportBackup[&quot;导入 .aihelper.json 备份&quot;]
ImportBackup --&gt; RestoreKB
RestoreKB --&gt; KBOk{&quot;知识库可用?&quot;}
KBOk --&gt; |否| RebuildRAG[&quot;重建 RAG 索引&quot;]
KBOk --&gt; |是| RestoreConfig[&quot;恢复用户配置&quot;]
RebuildRAG --&gt; RestoreConfig
RestoreConfig --&gt; End[&quot;完成恢复&quot;]
</pre><p><strong>图表来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/side_panel/export-import.js#L152-L220" target="_blank" rel="noreferrer">src/side_panel/export-import.js#L152-L220</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/storage/db.js#L626-L703" target="_blank" rel="noreferrer">src/storage/db.js#L626-L703</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js#L401-L407" target="_blank" rel="noreferrer">agent/src/server.js#L401-L407</a></li></ul><h2 id="依赖关系与架构总览" tabindex="-1">依赖关系与架构总览 <a class="header-anchor" href="#依赖关系与架构总览" aria-label="Permalink to &quot;依赖关系与架构总览&quot;">​</a></h2><p>扩展端与 Agent 端的交互是故障排查的核心。下图展示关键组件之间的依赖关系。</p><pre class="mermaid">graph LR
Manifest[&quot;manifest.json&lt;br/&gt;权限/入口/版本&quot;]
Background[&quot;background/index.js&lt;br/&gt;Service Worker 主逻辑&quot;]
DB[&quot;storage/db.js&lt;br/&gt;IndexedDB 封装&quot;]
ExportImport[&quot;side_panel/export-import.js&lt;br/&gt;会话导出导入&quot;]
ConfigManager[&quot;options/config-manager.js&lt;br/&gt;配置管理&quot;]
AgentServer[&quot;agent/server.js&lt;br/&gt;HTTP/WebSocket 服务&quot;]
InstallMode[&quot;agent/install-mode.js&lt;br/&gt;内嵌/npm 模式&quot;]
Security[&quot;agent/security.js&lt;br/&gt;路径与命令安全&quot;]
Manifest --&gt; Background
Background --&gt; DB
Background --&gt; AgentServer
ExportImport --&gt; DB
ConfigManager --&gt; Background
AgentServer --&gt; InstallMode
AgentServer --&gt; Security
</pre><p><strong>图表来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/manifest.json#L1-L76" target="_blank" rel="noreferrer">manifest.json#L1-L76</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/index.js#L1-L120" target="_blank" rel="noreferrer">src/background/index.js#L1-L120</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/storage/db.js#L21-L92" target="_blank" rel="noreferrer">src/storage/db.js#L21-L92</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/side_panel/export-import.js#L1-L47" target="_blank" rel="noreferrer">src/side_panel/export-import.js#L1-L47</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/options/config-manager.js#L1-L10" target="_blank" rel="noreferrer">src/options/config-manager.js#L1-L10</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js#L388-L500" target="_blank" rel="noreferrer">agent/src/server.js#L388-L500</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/install-mode.js#L1-L32" target="_blank" rel="noreferrer">agent/src/install-mode.js#L1-L32</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/security.js#L1-L18" target="_blank" rel="noreferrer">agent/src/security.js#L1-L18</a></li></ul><h2 id="故障排查清单" tabindex="-1">故障排查清单 <a class="header-anchor" href="#故障排查清单" aria-label="Permalink to &quot;故障排查清单&quot;">​</a></h2><h3 id="更新失败" tabindex="-1">更新失败 <a class="header-anchor" href="#更新失败" aria-label="Permalink to &quot;更新失败&quot;">​</a></h3><ul><li>[ ] 确认扩展版本与 Agent 版本一致；</li><li>[ ] 检查 npm 全局安装是否成功；</li><li>[ ] 查看 Agent 日志中是否有 <code>update_npm_failed</code>；</li><li>[ ] 确认没有 RAG 安装与更新并发；</li><li>[ ] 重启 Agent 后重试。</li></ul><h3 id="配置异常" tabindex="-1">配置异常 <a class="header-anchor" href="#配置异常" aria-label="Permalink to &quot;配置异常&quot;">​</a></h3><ul><li>[ ] 备份 <code>chrome.storage.local</code>；</li><li>[ ] 重置扩展设置；</li><li>[ ] 重新配置模型与 API Base；</li><li>[ ] 检查是否误删内置预设；</li><li>[ ] 若仍异常，清理 IndexedDB 后重建。</li></ul><h3 id="数据丢失" tabindex="-1">数据丢失 <a class="header-anchor" href="#数据丢失" aria-label="Permalink to &quot;数据丢失&quot;">​</a></h3><ul><li>[ ] 检查是否有 <code>.aihelper.json</code> 备份；</li><li>[ ] 尝试导入会话；</li><li>[ ] 检查 IndexedDB 中 <code>sessions</code> 与 <code>archivedSessions</code>；</li><li>[ ] 检查 ReAct checkpoint 是否因 TTL 过期被清理；</li><li>[ ] 必要时重置扩展数据并重新导入。</li></ul><h3 id="权限与安全" tabindex="-1">权限与安全 <a class="header-anchor" href="#权限与安全" aria-label="Permalink to &quot;权限与安全&quot;">​</a></h3><ul><li>[ ] 检查工作目录是否在白名单；</li><li>[ ] 检查是否尝试访问 Agent 核心敏感文件；</li><li>[ ] 检查命令是否命中黑名单或灰名单；</li><li>[ ] 确认 Agent 未对外暴露；</li><li>[ ] 审查扩展权限是否超出实际需求。</li></ul><h3 id="崩溃与恢复" tabindex="-1">崩溃与恢复 <a class="header-anchor" href="#崩溃与恢复" aria-label="Permalink to &quot;崩溃与恢复&quot;">​</a></h3><ul><li>[ ] 检查 Service Worker 是否被回收；</li><li>[ ] 查看是否有可恢复的 checkpoint；</li><li>[ ] 检查 IndexedDB 连接是否正常；</li><li>[ ] 重启扩展与 Agent；</li><li>[ ] 按灾难恢复流程逐步恢复数据。</li></ul><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js#L605-L720" target="_blank" rel="noreferrer">agent/src/server.js#L605-L720</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/storage/db.js#L626-L799" target="_blank" rel="noreferrer">src/storage/db.js#L626-L799</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/security.js#L109-L229" target="_blank" rel="noreferrer">agent/src/security.js#L109-L229</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/security.js#L691-L758" target="_blank" rel="noreferrer">agent/src/security.js#L691-L758</a></li></ul><h2 id="结论" tabindex="-1">结论 <a class="header-anchor" href="#结论" aria-label="Permalink to &quot;结论&quot;">​</a></h2><p>扩展相关问题的排查应以“扩展端 + Agent 端 + 本地存储”三位一体视角进行。更新失败多与 npm、端口、版本不一致有关；配置重置应优先备份用户设置；数据恢复应以会话导出文件为主、IndexedDB 为辅；卸载时必须清理 Agent 进程与文件残留；权限管理应遵循最小权限原则，并结合 Agent 的路径与命令安全策略。对于崩溃场景，扩展已提供 checkpoint 后备与自动续跑机制，但重大故障仍需人工介入并按灾难恢复流程处理。</p>`,182)])])}const b=r(l,[["render",o]]);export{p as __pageData,b as default};
